function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is an integer from 1 to 1000000000.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 entries.';
  let count = 0;
  for (let v = n; v > 0; v = Math.floor(v / 2)) count += v % 2;
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [left, right].';
    const [left, right] = query;
    if (!Number.isInteger(left) || !Number.isInteger(right)) return 'Query bounds are integers.';
    if (left < 0 || left > right || right >= count) return 'Each query needs 0 <= left <= right < powers.length.';
  }
  return null;
}

