function productQueries(n, queries) {
  const MOD = 1000000007;
  const prefix = [0];
  for (let bit = 0; bit < 30; bit++) {
    if ((n >> bit) & 1) {
      prefix.push(prefix[prefix.length - 1] + bit);
    }
  }

  const total = prefix[prefix.length - 1];
  const pow2 = [1];
  for (let exponent = 1; exponent <= total; exponent++) {
    pow2.push((pow2[exponent - 1] * 2) % MOD);
  }

  const answers = [];
  for (const [left, right] of queries) {
    answers.push(pow2[prefix[right + 1] - prefix[left]]);
  }
  return answers;
}

