function productQueries(n, queries) {
  const powers = [];
  let rest = n;
  while (rest > 0) {
    let p = 1;
    while (p * 2 <= rest) p *= 2;
    powers.push(p);
    rest -= p;
  }
  powers.reverse();
  const MOD = 1000000007n;
  return queries.map(([left, right]) => {
    let product = 1n;
    for (let j = left; j <= right; j++) product = (product * BigInt(powers[j])) % MOD;
    return Number(product);
  });
}

