function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let n;
  const shape = rand();
  if (shape < 0.15) n = 2 ** pick(0, 29);
  else if (shape < 0.3) n = 2 ** pick(1, 29) - 1;
  else if (shape < 0.5) n = pick(1, 64);
  else n = pick(1, 1000000000);
  let count = 0;
  for (let v = n; v > 0; v = Math.floor(v / 2)) count += v % 2;
  const q = size === 'large' ? 2000 : pick(1, 6);
  const queries = [];
  for (let i = 0; i < q; i++) {
    const a = pick(0, count - 1);
    const b = pick(0, count - 1);
    queries.push([Math.min(a, b), Math.max(a, b)]);
  }
  return [n, queries];
}
